from collections import Counter
def solve(I):
    H,W=len(I),len(I[0]); bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    # find largest connected non-bg component (template) and markers = other non-bg cells
    seen=[[False]*W for _ in range(H)]; best=None
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                stack=[(r,c)]; comp=[]; seen[r][c]=True
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<H and 0<=nb<W and not seen[na][nb] and I[na][nb]!=bg:
                                seen[na][nb]=True; stack.append((na,nb))
                if best is None or len(comp)>len(best): best=comp
    tr,tc=best[0]; T=[[I[tr+a][tc+b] for b in range(len({b for _,b in best}))] for a in range(len({a for a,_ in best}))]
    th,tw=len(T),len(T[0])
    markers=[(r,c) for r in range(H) for c in range(W) if I[r][c]!=bg and (r,c) not in set(best)]
